namespace {
using Statement=std::unique_ptr<sqlite3_stmt,decltype(&sqlite3_finalize)>;
void check(int code,sqlite3* db){if(code!=SQLITE_OK&&code!=SQLITE_DONE&&code!=SQLITE_ROW)throw std::runtime_error(sqlite3_errmsg(db));}
Statement statement(sqlite3* db,const char* sql){sqlite3_stmt* s=nullptr;check(sqlite3_prepare_v2(db,sql,-1,&s,nullptr),db);return {s,sqlite3_finalize};}
void exec(sqlite3* db,const char* sql){check(sqlite3_exec(db,sql,nullptr,nullptr,nullptr),db);}
void text(sqlite3_stmt* s,int i,const std::string& value){sqlite3_bind_text(s,i,value.c_str(),int(value.size()),SQLITE_TRANSIENT);}
struct Template{std::string payload,call,called,country,continent,grid,type,band,mode,message;int64_t dial=0;int audio=0,snr=0;std::optional<double> dt,km;};
std::filesystem::path owned(const char* input){auto file=std::filesystem::absolute(input).lexically_normal(),parent=std::filesystem::canonical(file.parent_path());std::ifstream marker(parent/".benchmark-owned");std::string owner;std::getline(marker,owner);
 if(file.filename()!="history.sqlite3"||parent.string().rfind("/private/tmp/advanced-dx-scale-",0)!=0||owner!="advanced-dx-scale-v1"||std::filesystem::is_symlink(file))throw std::runtime_error("Benchmark refuses a database outside its owned temporary directory");return file;
}
void seed(const std::filesystem::path& file,int64_t target){
 if(target<1||target>5000000)throw std::runtime_error("Benchmark target must be between 1 and 5000000");dx::Store store(file);sqlite3* raw=nullptr;check(sqlite3_open(file.c_str(),&raw),raw);std::unique_ptr<sqlite3,decltype(&sqlite3_close)> db(raw,sqlite3_close);sqlite3_busy_timeout(raw,2000);
 std::vector<Template> templates;auto read=statement(raw,"SELECT payload FROM decodes ORDER BY reception_id LIMIT 60000");
 while(sqlite3_step(read.get())==SQLITE_ROW){auto payload=reinterpret_cast<const char*>(sqlite3_column_text(read.get(),0));auto d=dx::Decode::fromJson(dx::Json::parse(payload));templates.push_back({payload,d.identity.transmitter,d.identity.called,d.country,d.continent,d.identity.grid,d.identity.type,dx::bandName(d.dial),d.mode,d.message,d.dial,d.audio,d.snr,d.dt,d.km});}read.reset();if(templates.empty())throw std::runtime_error("A real-data snapshot is required for representative templates");
 auto count=statement(raw,"SELECT count(*),max(reception_id),max(utc) FROM decodes");check(sqlite3_step(count.get()),raw);int64_t total=sqlite3_column_int64(count.get(),0),id=sqlite3_column_int64(count.get(),1),start=sqlite3_column_int64(count.get(),2);count.reset();
 // Disable every external side effect in the fixture profile.
 auto ui=store.getSetting("ui",dx::Json::object());ui["csv_path"]=(file.parent_path()/"receptions.csv").string();ui["history_all"]=true;ui["stats_history"]=true;ui["gridtracker"]={{"enabled",false}};ui["alerts"]={{"sound",false}};store.setSetting("ui",ui);store.setSetting("csv_paths",dx::Json::array());store.setSetting("cleanup_jobs",dx::Json::object());store.setSetting("log_purges",dx::Json::object());store.setSetting("message_log_purges",dx::Json::object());store.setSetting("compact_pending",false);
 auto insert=statement(raw,"INSERT INTO decodes(reception_id,key,utc,dial,mode,call,called,country,continent,grid,type,band,snr,dt,km,message,payload) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,json_set(?,'$.timestamp',?,'$.slot_ms',?,'$.source','benchmark'))");
 auto station=statement(raw,"INSERT INTO stations(call,dial,mode,utc,count,payload) VALUES(?,?,?,?,1,json_set(?,'$.timestamp',?,'$.slot_ms',?,'$.source','benchmark')) ON CONFLICT(call,dial,mode) DO UPDATE SET count=count+1,utc=max(utc,excluded.utc),payload=CASE WHEN excluded.utc>=utc THEN excluded.payload ELSE payload END");
 const auto began=dx::monotonicMs();int64_t added=0;
 while(total<target){if(std::filesystem::space(file.parent_path()).available<2ULL*1024*1024*1024)throw std::runtime_error("Benchmark stopped to preserve 2 GB of free disk space");exec(raw,"BEGIN IMMEDIATE");int64_t chunk=std::min<int64_t>(10000,target-total);
  for(int64_t j=0;j<chunk;j++){auto& t=templates[size_t((total+j)%templates.size())];auto utc=start+(added+j)/6*15;sqlite3_reset(insert.get());sqlite3_clear_bindings(insert.get());sqlite3_bind_int64(insert.get(),1,++id);text(insert.get(),2,"benchmark:"+std::to_string(id));sqlite3_bind_int64(insert.get(),3,utc);sqlite3_bind_int64(insert.get(),4,t.dial);text(insert.get(),5,t.mode);text(insert.get(),6,t.call);text(insert.get(),7,t.called);text(insert.get(),8,t.country);text(insert.get(),9,t.continent);text(insert.get(),10,t.grid);text(insert.get(),11,t.type);text(insert.get(),12,t.band);sqlite3_bind_int(insert.get(),13,t.snr);if(t.dt)sqlite3_bind_double(insert.get(),14,*t.dt);if(t.km)sqlite3_bind_double(insert.get(),15,*t.km);text(insert.get(),16,t.message);text(insert.get(),17,t.payload);sqlite3_bind_int64(insert.get(),18,utc);sqlite3_bind_int64(insert.get(),19,utc*1000);check(sqlite3_step(insert.get()),raw);
   if(!t.call.empty()){sqlite3_reset(station.get());text(station.get(),1,t.call);sqlite3_bind_int64(station.get(),2,t.dial);text(station.get(),3,t.mode);sqlite3_bind_int64(station.get(),4,utc);text(station.get(),5,t.payload);sqlite3_bind_int64(station.get(),6,utc);sqlite3_bind_int64(station.get(),7,utc*1000);check(sqlite3_step(station.get()),raw);}
  }
  exec(raw,"COMMIT");total+=chunk;added+=chunk;if(total%100000<10000||total==target)std::cout<<dx::Json({{"seed_rows",total},{"elapsed_seconds",(dx::monotonicMs()-began)/1000.},{"file_MB",std::filesystem::file_size(file)/1e6}}).dump()<<std::endl;
 }
 exec(raw,"UPDATE counters SET value=(SELECT count(*) FROM decodes) WHERE key='messages';INSERT OR REPLACE INTO counters VALUES('reception_id',(SELECT max(reception_id) FROM decodes));PRAGMA wal_checkpoint(TRUNCATE)");
}
dx::Json measure(const std::filesystem::path& file){auto opened=dx::monotonicMs();dx::Store store(file);auto openMs=dx::monotonicMs()-opened;sqlite3* raw=nullptr;check(sqlite3_open_v2(file.c_str(),&raw,SQLITE_OPEN_READONLY,nullptr),raw);std::unique_ptr<sqlite3,decltype(&sqlite3_close)> db(raw,sqlite3_close);
 auto s=statement(raw,"SELECT count(*),max(utc),max(reception_id) FROM decodes");check(sqlite3_step(s.get()),raw);auto total=sqlite3_column_int64(s.get(),0),reference=sqlite3_column_int64(s.get(),1),last=sqlite3_column_int64(s.get(),2);s.reset();dx::Json result={{"records",total},{"file_MB",std::filesystem::file_size(file)/1e6},{"sqlite",sqlite3_libversion()},{"open_ms",openMs}};
 auto timed=[&](const char* name,auto action){auto began=dx::monotonicMs();action();result[name]=dx::monotonicMs()-began;std::cout<<dx::Json({{"query",name},{"milliseconds",result[name]}}).dump()<<std::endl;};
 timed("all_stats_ms",[&]{auto stats=store.stats(reference);result["countries"]=stats.countries;result["stations"]=stats.stations;});
 timed("all_session_stats_ms",[&]{store.sessionStats(reference,0,0);});timed("recent_session_stats_ms",[&]{store.sessionStats(reference,std::max<int64_t>(0,last-10000),reference-86400);});
 timed("recent_session_cached_ms",[&]{store.sessionStats(reference,std::max<int64_t>(0,last-10000),reference-86400);});
 dx::Query q;q.uniqueCalls=true;q.sort=17;timed("unique_first_page_ms",[&]{store.rows(q,0,500);});timed("unique_count_ms",[&]{int64_t count=0;store.rows(q,0,0,&count);result["unique_rows"]=count;});
 q.messages=true;q.uniqueCalls=false;q.sort=18;timed("all_messages_first_page_ms",[&]{store.rows(q,0,500);});timed("all_messages_count_ms",[&]{int64_t count=0;store.rows(q,0,0,&count);});
 q={};q.uniqueCalls=true;q.filter.country="United States";timed("country_filter_ms",[&]{store.rows(q,0,500);});q.filter.country.clear();q.filter.search="CQ";timed("search_ms",[&]{store.rows(q,0,500);});
 q={};q.uniqueCalls=true;q.sort=0;timed("countries_table_ms",[&]{dx::countrySummaries(store.rows(q));});q.since=reference-900;q.until=reference;timed("recent_view_ms",[&]{store.rows(q);});
 q={};q.pathCount=3;q.pathSpectrum=std::make_pair(7070000.,7080000.);timed("exchange_paths_ms",[&]{store.exchangePaths(q);});
 auto quick=statement(raw,"PRAGMA quick_check");check(sqlite3_step(quick.get()),raw);result["quick_check"]=reinterpret_cast<const char*>(sqlite3_column_text(quick.get(),0));return result;
}
dx::Json trim(const std::filesystem::path& file,int64_t limit,int batch){
 dx::Store store(file);auto before=store.savedMessageCount(),watermark=store.lastReceptionId(),start=dx::monotonicMs();int64_t removed=0,worst=0,batches=0;
 do{auto began=dx::monotonicMs();auto count=store.retain(limit,batch,watermark);worst=std::max(worst,dx::monotonicMs()-began);removed+=count;++batches;store.reclaimPages(32);if(batches%1000==0)std::cout<<dx::Json({{"deleted",removed},{"seconds",(dx::monotonicMs()-start)/1000.},{"worst_batch_ms",worst}}).dump()<<std::endl;}while(store.retentionState().running);
 if(store.lastReceptionId()!=watermark||store.savedMessageCount()!=before-removed)throw std::runtime_error("Retention watermark/count mismatch");
 sqlite3* raw=nullptr;check(sqlite3_open_v2(file.c_str(),&raw,SQLITE_OPEN_READONLY,nullptr),raw);std::unique_ptr<sqlite3,decltype(&sqlite3_close)> db(raw,sqlite3_close);auto verify=statement(raw,"PRAGMA integrity_check");check(sqlite3_step(verify.get()),raw);auto integrity=reinterpret_cast<const char*>(sqlite3_column_text(verify.get(),0));if(std::string(integrity)!="ok")throw std::runtime_error("Retention integrity check failed");
 return {{"before",before},{"after",store.savedMessageCount()},{"removed",removed},{"batch_size",batch},{"batches",batches},{"worst_batch_ms",worst},{"seconds",(dx::monotonicMs()-start)/1000.},{"integrity_check",integrity}};
}
dx::Json engineMeasure(const std::filesystem::path& file){
 auto root=file.parent_path();if(std::filesystem::exists(root.parent_path()/"FT8 Map/history.sqlite3")||std::filesystem::exists(root.parent_path()/"sdrpp-brown/ft8_decoder_config.json"))throw std::runtime_error("Benchmark refuses an external legacy source");
 dx::Point home{NAN,NAN};int64_t records=0;
 {dx::Store store(file);auto origin=store.getSetting("distance_origin",nullptr);if(origin.is_array()&&origin.size()==2)home={origin[0].get<double>(),origin[1].get<double>()};records=store.savedMessageCount();auto ui=store.getSetting("ui",dx::Json::object());ui["history_auto_trim"]=false;ui["history_all"]=true;ui["csv_path"]=(root/"receptions.csv").string();store.setSetting("ui",ui);store.setSetting("csv_paths",dx::Json::array({(root/"receptions.csv").string()}));store.setSetting("csv_floors",{{(root/"receptions.csv").string(),store.lastReceptionId()}});store.setSetting("country_schema",3);}
 dx::Engine engine(root,root/"unused-helper",home,[](const std::string&){return std::make_pair(std::string{},std::string{});});uint64_t generation=20;dx::Json result={{"records",records}};
 auto run=[&](const char* name,dx::Query q){auto map=q;map.messages=map.countries=map.uniqueCalls=false;map.sort=0;auto start=dx::monotonicMs();engine.query(q,map,++generation);while(dx::monotonicMs()-start<45000){auto snapshot=engine.snapshot();if(snapshot->generation==generation){if(!snapshot->error.empty())throw std::runtime_error(snapshot->error);result[name]={{"end_to_end_ms",dx::monotonicMs()-start},{"query_ms",snapshot->queryMs},{"rows",snapshot->tableCount}};std::cout<<dx::Json({{"view",name},{"result",result[name]}}).dump()<<std::endl;return;}std::this_thread::sleep_for(std::chrono::milliseconds(1));}throw std::runtime_error("Engine benchmark query exceeded 45 seconds");};
 dx::Query q;q.uniqueCalls=true;q.sort=17;run("unique_stations",q);q.messages=true;q.uniqueCalls=false;q.sort=18;run("all_messages",q);q={};q.uniqueCalls=true;q.filter.search="CQ";run("search_CQ",q);q.filter.search="NO SUCH MESSAGE";run("empty_search",q);q.filter={};q.filter.country="United States";run("country_filter",q);q.filter={};q.filter.mode="FT8";q.filter.band="40m";run("band_mode_filter",q);q.filter={};q.sort=3;run("distance_sort",q);q.sort=4;run("snr_sort",q);q.countries=true;q.sort=5;run("countries_heard",q);return result;
}
dx::Json soak(const std::filesystem::path& file){
 dx::Store store(file);store.unignoreAll();auto origin=store.getSetting("distance_origin",nullptr);dx::Point home{NAN,NAN};if(origin.is_array())home={origin[0].get<double>(),origin[1].get<double>()};dx::Query q;q.messages=true;auto templates=store.rows(q,0,500);if(templates.empty())throw std::runtime_error("Soak requires reception templates");
 auto original=store.savedMessageCount(),watermark=store.lastReceptionId(),start=dx::monotonicMs();int64_t received=0,removed=0,worst=0,batches=0,reference=int64_t(time(nullptr))+86400;
 store.sessionStats(reference,0,1);
 auto clean=[&]{if(store.savedMessageCount()<=50000&&!store.retentionState().running)return;do{auto began=dx::monotonicMs();removed+=store.retain(50000,64);auto cached=store.sessionStats(reference,0,1);worst=std::max(worst,dx::monotonicMs()-began);++batches;if(cached.messages!=store.savedMessageCount())throw std::runtime_error("Long-session cache count mismatch");store.reclaimPages(32);}while(store.retentionState().running);auto cached=store.sessionStats(reference,0,1),actual=store.stats(reference);if(cached.countries!=actual.countries||cached.stations!=actual.stations||cached.newestCountries!=actual.newestCountries)throw std::runtime_error("Long-session summary mismatch");};clean();
 for(int cycle=0;cycle<12;cycle++){
  int accepted=0;for(int i=0;accepted<5001&&i<20000;i++){auto d=templates[size_t(i)%templates.size()].decode;d.utc=reference+15*i;d.slotMs=d.utc*1000;d.source="benchmark";if(store.insert(d,home)){++received;++accepted;}}if(accepted!=5001)throw std::runtime_error("Soak could not generate enough unique receptions");reference+=7*86400;store.sessionStats(reference,0,1);clean();if(store.savedMessageCount()>50000||store.lastReceptionId()<=watermark)throw std::runtime_error("Soak limit/ID mismatch");watermark=store.lastReceptionId();std::cout<<dx::Json({{"cycle",cycle+1},{"records",store.savedMessageCount()},{"worst_batch_with_stats_ms",worst}}).dump()<<std::endl;
 }
 if(store.savedMessageCount()!=original+received-removed)throw std::runtime_error("Soak conservation mismatch");sqlite3* raw=nullptr;check(sqlite3_open_v2(file.c_str(),&raw,SQLITE_OPEN_READONLY,nullptr),raw);std::unique_ptr<sqlite3,decltype(&sqlite3_close)> db(raw,sqlite3_close);auto verify=statement(raw,"PRAGMA integrity_check");check(sqlite3_step(verify.get()),raw);std::string integrity=reinterpret_cast<const char*>(sqlite3_column_text(verify.get(),0));if(integrity!="ok")throw std::runtime_error("Soak integrity failure");return {{"cycles",12},{"records",store.savedMessageCount()},{"received",received},{"deleted",removed},{"batches",batches},{"worst_batch_with_stats_ms",worst},{"seconds",(dx::monotonicMs()-start)/1000.},{"integrity_check",integrity}};
}
}
int main(int argc,char** argv){try{if(argc<3||argc>5)return 2;auto file=owned(argv[2]);if(std::string(argv[1])=="engine"&&argc==3){auto result=engineMeasure(file);std::ofstream(file.parent_path()/("engine-"+std::to_string(result["records"].get<int64_t>())+".json"))<<result.dump(2)<<'\n';std::cout<<result.dump(2)<<std::endl;return 0;}if(std::string(argv[1])=="soak"&&argc==3){auto result=soak(file);std::ofstream(file.parent_path()/"soak.json")<<result.dump(2)<<'\n';std::cout<<result.dump(2)<<std::endl;return 0;}if(std::string(argv[1])=="seed"&&argc==4){seed(file,std::stoll(argv[3]));return 0;}if(std::string(argv[1])=="trim"&&(argc==4||argc==5)){auto result=trim(file,std::stoll(argv[3]),argc==5?std::stoi(argv[4]):64);std::ofstream(file.parent_path()/("trim-"+std::to_string(result["after"].get<int64_t>())+".json"))<<result.dump(2)<<'\n';std::cout<<result.dump(2)<<std::endl;return 0;}if(std::string(argv[1])=="measure"&&argc==3){auto result=measure(file);std::ofstream(file.parent_path()/("measure-"+std::to_string(result["records"].get<int64_t>())+".json"))<<result.dump(2)<<'\n';std::cout<<result.dump(2)<<std::endl;return result["quick_check"]=="ok"?0:1;}return 2;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
